// ---- helpers ---------------------------------------------------------------
// Settings come from the container environment (ai/.env)
const setting = (name, fallback) => {
    const value = $env[name];
    return value === undefined || value === '' ? fallback : String(value);
};
const seconds = (name, fallback) => {
    const value = Number(setting(name, fallback));
    return (Number.isFinite(value) && value >= 0 ? value : fallback) * 1000;
};
// InfluxDB CSV (header row, no annotations) → array of objects
function parseCsv(text) {
    const rows = [];
    let row = [], field = '', quoted = false;
    for (let i = 0; i < text.length; i++) {
        const c = text[i];
        if (quoted) {
            if (c === '"' && text[i + 1] === '"') { field += '"'; i++; }
            else if (c === '"') quoted = false;
            else field += c;
        } else if (c === '"') quoted = true;
        else if (c === ',') { row.push(field); field = ''; }
        else if (c === '\r' || c === '\n') {
            if (c === '\r' && text[i + 1] === '\n') i++;
            row.push(field); field = '';
            if (row.some((v) => v !== '')) rows.push(row);
            row = [];
        } else field += c;
    }
    if (field !== '' || row.length) { row.push(field); if (row.some((v) => v !== '')) rows.push(row); }
    const out = [];
    let header = null;
    for (const r of rows) {
        if (r[1] === 'result' && r[2] === 'table') { header = r; continue; }
        if (header) out.push(Object.fromEntries(header.map((h, i) => [h, r[i]])));
    }
    return out;
}
// Line protocol escaping
const tag = (v) => String(v).replace(/[\\, =]/g, (c) => '\\' + c);
const str = (v) => '"' + String(v).replace(/[\\"]/g, (c) => '\\' + c) + '"';
const esc = (v) => String(v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmt = (t) => (t === null || t === undefined || Number.isNaN(t) ? '–' : (Math.round(t * 10) / 10).toFixed(1) + ' °C');
const minutes = (ms) => Math.max(0, Math.round(ms / 60000));
const label = (u) => (u.name || u.id) + (u.location ? ' (' + u.location + ')' : '');
// A time as people read it, in the project's timezone (TZ)
const when = (t) => DateTime.fromMillis(typeof t === 'number' ? t : Date.parse(t), { zone: setting('GENERIC_TIMEZONE', 'UTC') })
    .toFormat('yyyy-MM-dd HH:mm ZZZZ');
// The ack link carries a signature, so only links from an alert work
const crypto = require('crypto');
const sign = (device, excursion) => crypto.createHmac('sha256', setting('ACK_SECRET', ''))
    .update(device + '|' + excursion).digest('hex').slice(0, 32);

// GET /webhook/coldchain/ack?device=…&excursion=…&token=… (the link in an alert)
const q = $('Ack link').first().json.query || {};
const page = (title, body) => '<!doctype html><html><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width, initial-scale=1"><title>' + esc(title) + '</title>'
    + '<style>body{font-family:system-ui,sans-serif;max-width:32rem;margin:2rem auto;padding:0 1rem;line-height:1.5}'
    + 'label{display:block;margin-top:1rem;font-weight:600}input,textarea{width:100%;padding:.5rem;font:inherit;box-sizing:border-box}'
    + 'button{margin-top:1rem;padding:.6rem 1.2rem;font:inherit}</style></head><body>' + body + '</body></html>';
if (!q.device || !q.excursion || q.token !== sign(q.device, q.excursion)) {
    return [{ json: { status: 400, html: page('Invalid link', '<h1>Invalid link</h1><p>Use the link in the alert email.</p>') } }];
}
const units = $('Parse units').first().json.units || [];
const unit = units.find((u) => u.id === q.device) || { id: q.device };
const hidden = (name, value) => '<input type="hidden" name="' + name + '" value="' + esc(value) + '">';
return [{ json: { status: 200, html: page('Acknowledge excursion', '<h1>Acknowledge excursion</h1>'
    + '<p><b>' + esc(label(unit)) + '</b>' + (unit.min !== undefined ? ', limits ' + unit.min + '–' + unit.max + ' °C' : '')
    + '<br>Out of range since ' + esc(when(q.excursion)) + '</p>'
    + '<form method="post">' + hidden('device', q.device) + hidden('excursion', q.excursion) + hidden('token', q.token)
    + '<label for="by">Your name</label><input id="by" name="by" required maxlength="80">'
    + '<label for="action">Corrective action taken</label>'
    + '<textarea id="action" name="action" rows="4" required maxlength="1000" placeholder="e.g. Door closed, stock moved to fridge-01, product quarantined pending QA"></textarea>'
    + '<button type="submit">Acknowledge</button></form>') } }];

